#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
const int N = 100005;
ll a[N], sum[N << 2], tag[N << 2];
void pushup(int p) { sum[p] = sum[p << 1] + sum[p << 1 | 1]; }
void build(int p, int l, int r) {
    if (l == r) { sum[p] = a[l]; return; }
    int m = (l + r) >> 1;
    build(p << 1, l, m);
    build(p << 1 | 1, m + 1, r);
    pushup(p);
}
void update(int p, int l, int r, int x, int y, ll k) {
    if (x <= l && r <= y) { sum[p] += k * (r - l + 1); tag[p] += k; return; }
    int m = (l + r) >> 1;
    if (x <= m) update(p << 1, l, m, x, y, k);
    if (y > m) update(p << 1 | 1, m + 1, r, x, y, k);
    pushup(p);
}
ll query(int p, int l, int r, int x, int y) {
    if (x <= l && r <= y) return sum[p];
    int m = (l + r) >> 1;
    ll res = 0;
    if (x <= m) res += query(p << 1, l, m, x, y);
    if (y > m) res += query(p << 1 | 1, m + 1, r, x, y);
    return res;
}
int main() {
    int n, m;
    cin >> n >> m;
    for (int i = 1; i <= n; i++) cin >> a[i];
    build(1, 1, n);
    while (m--) {
        int op, x, y;
        cin >> op >> x >> y;
        if (op == 1) { ll k; cin >> k; update(1, 1, n, x, y, k); }
        else cout << query(1, 1, n, x, y) << endl;
    }
    return 0;
}

你现在用的是埃氏筛，n 到 10^8 时 O(n log log n) 偏慢，换成线性筛 O(n)。代码如下：
